#include "MicroTuning.h"
#include "ControlEdits.h"
static void testMicroTuning(const File& root,Assets& assets){
    MicroTuning tuning,read;expect(validateMicroTuning(tuning).wasOk()&&microTuningCents(tuning,69)==0&&microTuningFrequency(tuning,69)==440,"neutral tuning retains standard A4 exactly");
    expect(equalDivisionTuning(24,60,440,tuning).wasOk()&&tuning.cents[60]==0&&tuning.cents[61]==-50&&tuning.cents[59]==50&&std::abs(microTuningFrequency(tuning,84)/microTuningFrequency(tuning,60)-2)<1e-12,"24 EDO maps adjacent keys to quartertones around the chosen root");
    for(int divisions:{5,12,19,24,31,53,72})for(int anchor:{0,60,127}){expect(equalDivisionTuning(divisions,anchor,432,tuning).wasOk(),"bounded equal division tables accept every root");for(int n=0;n<127;++n)expect(std::abs(microTuningFrequency(tuning,n+1)/microTuningFrequency(tuning,n)-std::exp2(1./divisions))<1e-10,"all adjacent keys follow declared EDO ratio including negative root distances");}
    auto saved=tuning;for(auto args:{std::pair{4,60},std::pair{73,60},std::pair{12,-1},std::pair{12,128}})expect(equalDivisionTuning(args.first,args.second,440,tuning).failed()&&tuning==saved,"invalid EDO rejects without replacing the destination");
    const String just="! example.scl\nFive notes and an octave\n5\n9/8 C#\n5/4\n3/2\n7/4\n2\n";
    expect(scalaTuning(just,60,440,tuning).wasOk()&&std::abs(microTuningFrequency(tuning,61)/microTuningFrequency(tuning,60)-9./8)<1e-12&&std::abs(microTuningFrequency(tuning,59)/microTuningFrequency(tuning,60)-7./8)<1e-12&&std::abs(microTuningFrequency(tuning,65)/microTuningFrequency(tuning,60)-2)<1e-12,"Scala ratios, integer period, trailing labels and below-root mapping follow the scale");
    expect(scalaTuning("! blank description\n\n13\n-5.0 cents\n100.0\n200.0\n300.0\n400.0\n500.0\n600.0\n700.0\n800.0\n900.0\n1000.0\n1100.0\n3/1\n",60,440,read).wasOk()&&read.name=="Imported Scala scale"&&read.cents[61]==-105&&std::abs(microTuningFrequency(read,73)/microTuningFrequency(read,60)-3)<1e-12,"Scala supports empty descriptions, negative intervals and non-octave periods");
    expect(scalaTuning("Cent scale\n12\n700.0\n200.0\n300.0\n400.0\n500.0\n600.0\n700.0\n800.0\n900.0\n1000.0\n1100.0\n1200.0\n",60,432,read).wasOk()&&read.cents[61]==600&&read.cents[59]==0,"Scala cents values are distinguished from integer ratios");
    auto before=read;for(auto bad:{"Bad\n0\n","Bad\n129\n2\n","Bad\n2\n100.0\n","Bad\n1\n0/1\n","Bad\n1\n1/0\n","Bad\n1\n1/2/3\n","Bad\n1\nnan\n","Bad\n1\n-1200.0\n","Bad\n1\n5000.0\n","Bad\n1\n2\n3\n"})expect(scalaTuning(bad,60,440,read).failed()&&read==before,"invalid Scala rejects atomically");
    expect(scalaTuning(String::repeatedString("a",65537),60,440,read).failed()&&read==before,"oversized Scala text rejects before parsing");
    auto folder=root.getChildFile("microtuning-core");folder.createDirectory();auto preset=folder.getChildFile("custom.pulsetuning");expect(saveMicroTuning(tuning,preset).wasOk()&&loadMicroTuning(preset,0,880,read).wasOk()&&read==tuning,"local tuning preset stores exact mapping independent of future import root/reference");auto invalid=tuning;invalid.cents[3]=std::nan("");auto bytes=preset.loadFileAsString();expect(saveMicroTuning(invalid,preset).failed()&&preset.loadFileAsString()==bytes,"invalid tuning cannot overwrite a valid preset");
    for(int bad=0;bad<8;++bad){auto json=microTuningToJson(tuning);auto offsets=*json["cents"].getArray();if(bad==0)json.getDynamicObject()->setProperty("enabled",1);if(bad==1)json.getDynamicObject()->setProperty("referenceHz",true);if(bad==2)json.getDynamicObject()->setProperty("referenceHz",1000);if(bad==3)offsets.removeLast();if(bad==4)offsets.getReference(5)="3";if(bad==5)offsets.getReference(5)=24001;if(bad==6)json.getDynamicObject()->setProperty("extra",0);if(bad==7)json.getDynamicObject()->setProperty("name","bad\nname");json.getDynamicObject()->setProperty("cents",offsets);auto prior=read;expect(microTuningFromJson(json,read).failed()&&read==prior,"malformed tuning types, size, bounds, name and unknown fields reject atomically");}
    auto song=emptyProject();song.loop=false;song.bpm=120;auto& track=song.tracks[7];track.tuning=tuning;track.send=0;track.volume=.7f;track.cutoff=20000;song.patterns[0].lanes[7]={{0,2,64,.8f}};Project loaded;expect(projectFromJson(projectToJson(song),loaded).wasOk()&&loaded.tracks[7].tuning==tuning,"project schema 23 embeds complete per-instrument tuning");auto file=folder.getChildFile("tuned.pulse");expect(saveProject(song,file).wasOk()&&loadProject(file,loaded).wasOk()&&loaded.tracks[7].tuning==tuning,"checked project save and load retain every tuning offset");
    for(int schema=1;schema<=22;++schema){auto json=projectToJson(emptyProject());json.getDynamicObject()->setProperty("schema",schema);for(auto& t:*json["tracks"].getArray())t.getDynamicObject()->removeProperty("tuning");expect(projectFromJson(json,loaded).wasOk()&&loaded.tracks[7].tuning==MicroTuning{},"every legacy schema migrates to disabled neutral channel tuning");}
    auto retained=JSON::toString(projectToJson(loaded));auto json=projectToJson(song);json.getDynamicObject()->setProperty("schema",22);expect(projectFromJson(json,loaded).failed()&&JSON::toString(projectToJson(loaded))==retained,"nondefault tuning cannot be hidden in an old project schema");json=projectToJson(song);json["tracks"][7].getDynamicObject()->removeProperty("tuning");expect(projectFromJson(json,loaded).failed(),"current projects require complete tuning state");
    // Measure actual rendered audio, with independent routes for old oscillators and four new engines.
    for(auto instrument:{Instrument::bass,Instrument::pad,Instrument::lead,Instrument::analog,Instrument::fm,Instrument::wavetable,Instrument::additive}){
        track.instrument=instrument;track.synth={};track.synth.wave1=0;track.synth.wave2=0;track.synth.mix=0;track.synth.sub=0;track.synth.noise=0;track.synth.fmIndex=0;track.synth.cutoff=20000;track.synth.resonance=0;track.synth.table=0;track.synth.tablePosition=0;track.synth.harmonics.fill(0);track.synth.harmonics[0]=1;
        track.tuning={};track.tuning.enabled=true;track.tuning.referenceHz=432;track.tuning.cents[64]=-37.5;auto audio=render(song,assets,folder,24000);double expected=microTuningFrequency(track.tuning,64),measured=tuningFrequency(audio,48000);if(instrument==Instrument::bass||instrument==Instrument::pad){SamplePitch detected;auto result=detectSamplePitch(audio,48000,4800,21600,detected);measured=result.wasOk()?detected.frequency:0;}expect(measured>0&&std::abs(1200*std::log2(measured/expected))<(instrument==Instrument::pad?7:3),("actual bundled instrument pitch / "+instrumentName(instrument)+" / measured "+String(measured,6)+" / target "+String(expected,6)).toRawUTF8());expect(audio==render(song,assets,folder,24000,127),"tuned instrument output is independent of callback block size");
        auto standard=song;standard.tracks[7].tuning={};track.tuning.enabled=false;expect(render(song,assets,folder,8000)==render(standard,assets,folder,8000),"bypassing a retained custom table restores exact standard audio");
    }
    auto tone=tuningTone(48000,220,1);auto sample=folder.getChildFile("A3.wav");{auto stream=sample.createOutputStream();WavAudioFormat format;std::unique_ptr<AudioFormatWriter> writer(format.createWriterFor(stream.get(),48000,2,24,{},0));if(writer){stream.release();writer->writeFromAudioSampleBuffer(tone,0,tone.getNumSamples());}}
    track.instrument=Instrument::sample;track.samplePath=sample.getFullPathName();track.sampleRoot=57;track.sampleTune=-12.5;track.tuning.enabled=true;track.tuning.referenceHz=432;track.tuning.cents[64]=50;track.sampleLoop=true;
    expect(std::abs(tuningFrequency(render(song,assets,folder,24000),48000)-microTuningFrequency(track.tuning,64)*std::exp2(-12.5/1200))<.3,"sampler combines source root/fine calibration with target microtonal pitch");
    for(int rate:{44100,48000,96000}){RenderSettings settings;settings.sampleRate=rate;settings.bits=32;settings.tailSeconds=0;settings.endBeat=1;auto path=folder.getChildFile("pitch-"+String(rate)+".wav");expect(renderAudio(song,assets,folder,path,settings).wasOk(),"microtonal float export succeeds at every export sample rate");AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(path));AudioBuffer<float> audio(2,rate/2);bool readOk=reader&&reader->read(&audio,0,audio.getNumSamples(),0,true,true);expect(readOk&&std::abs(tuningFrequency(audio,rate)-microTuningFrequency(track.tuning,64)*std::exp2(-12.5/1200))<.3,"actual exported sampler pitches follow the tuning independently of export sample rate");}
    auto extreme=song;extreme.tracks[7].sampleRoot=0;extreme.tracks[7].sampleTune=100;extreme.tracks[7].sampleLoop=false;extreme.tracks[7].tuning.referenceHz=880;extreme.tracks[7].tuning.cents[127]=24000;extreme.patterns[0].lanes[7][0].pitch=127;auto exhausted=render(extreme,assets,folder,1024);expect(exhausted.getMagnitude(0,10,1014)==0,"extreme one-shot tuning exhausts safely before integer sample-index conversion");
    auto chased=makeEngine(song,assets,folder);chased->seekRequested.store(.25);AudioBuffer<float> a(2,1024),b(2,1024);chased->render(a.getWritePointer(0),a.getWritePointer(1),1024);auto offset=song;offset.tracks[7].sampleStart=.125*samplerRatio(64,57,-12.5)*std::exp2(microTuningCents(track.tuning,64)/1200);auto regular=makeEngine(offset,assets,folder);regular->render(b.getWritePointer(0),b.getWritePointer(1),1024);float difference=0;for(int ch=0;ch<2;++ch)for(int n=0;n<1024;++n)difference=jmax(difference,std::abs(a.getSample(ch,n)-b.getSample(ch,n)));expect(chased->chasedNotes.load()==1&&difference<.00001f,"sampler seek chase includes microtonal pitch in source position");
    Project edited;auto* op=new DynamicObject();op->setProperty("op","set_track");op->setProperty("track",7);op->setProperty("tuning",microTuningToJson(track.tuning));Array<var> ops{var(op)};expect(applyControlEdits(emptyProject(),ops,edited).wasOk()&&edited.tracks[7].tuning==track.tuning,"MCP replaces a complete per-channel tuning table atomically");auto output=JSON::toString(projectToJson(edited));op->setProperty("track",16);expect(applyControlEdits(emptyProject(),ops,edited).failed()&&JSON::toString(projectToJson(edited))==output,"MCP rejects invalid target without changing output");op->setProperty("track",7);op->setProperty("tuning",microTuningToJson(invalid));expect(applyControlEdits(emptyProject(),ops,edited).failed()&&JSON::toString(projectToJson(edited))==output,"MCP refuses nonfinite tuning as a whole batch");
    auto playback=std::make_unique<Playback>();String warnings;song.tracks[7].tuning=invalid;expect(compilePlayback(song,assets,folder,*playback,warnings).failed(),"invalid tuning cannot enter the audio callback");
}
